  en:{business:'Business Dashboard',education:'Education Dashboard',journey:'Guided Journey',profile:'My Profile',schemes:'Scheme Discovery',documents:'Documents',partners:'Partner Match',calculator:'Financial Calculator',applications:'My Applications',start:'Start application',compare:'Compare schemes',offline:'Offline',online:'Online',sync:'Sync now',refresh:'Refresh',save:'Save',submit:'Submit application',directions:'Directions',select:'Select partner',why:'Why this recommendation?',readiness:'Application readiness',status:'Application status'},
