function getStoredLanguage(){try{const value=localStorage.getItem('aarambh_lang');return I18N[value]?value:'en'}catch{return 'en'}}

function Btn({children,variant='',icon:Icon,onClick,type='button',disabled=false}){return <button type={type} disabled={disabled} onClick={onClick} className={'btn '+variant}>{Icon&&<Icon size={17}/>} {children}</button>}
function Card({children,className=''}){return <div className={'card '+className}>{children}</div>}
function Pill({children,tone=''}){return <span className={'pill '+tone}>{children}</span>}
function Modal({title,children,onClose}){return <div className="modal"><div className="modal-box"><div className="row between"><h3>{title}</h3><button className="icon-btn" onClick={onClose}><X size={19}/></button></div>{children}</div></div>}
function Stat({title,value,sub}){return <Card className="stat-card"><small>{title}</small><b>{value}</b><span>{sub}</span></Card>}
function Empty({icon:Icon=FileText,text}){return <div className="empty"><Icon/><p>{text}</p></div>}
function fmtMoney(v){return `₹${Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:0})}`}
function distanceKm(a,b,c,d){if([a,b,c,d].some(v=>v==null||Number.isNaN(Number(v))))return Infinity;const R=6371, p=Math.PI/180, dLat=(c-a)*p,dLon=(d-b)*p;const x=Math.sin(dLat/2)**2+Math.cos(a*p)*Math.cos(c*p)*Math.sin(dLon/2)**2;return 2*R*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}


function getSpeechLocale(lang){return lang==='ta'?'ta-IN':lang==='hi'?'hi-IN':'en-IN'}
function parseSpokenNumber(text){const t=text.toLowerCase().replace(/,/g,'').trim();const digitLakh=t.match(/(\d+(?:\.\d+)?)\s*(lakh|lakhs|லட்சம்|लाख)/);if(digitLakh)return Number(digitLakh[1])*100000;const digit=t.match(/\d+(?:\.\d+)?/);if(digit)return Number(digit[0]);const words={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,ஒன்று:1,இரண்டு:2,மூன்று:3,நான்கு:4,ஐந்து:5,ஆறு:6,ஏழு:7,எட்டு:8,ஒன்பது:9,பத்து:10,ஒரு:1,एक:1,दो:2,तीन:3,चार:4,पाँच:5,पांच:5,छह:6,सात:7,आठ:8,नौ:9,दस:10};for(const [w,n] of Object.entries(words)){if(new RegExp('(?:^|\\s)'+w+'\\s*(?:lakh|lakhs|லட்சம்|लाख)').test(t))return n*100000;}for(const [w,n] of Object.entries(words))if(t.includes(w))return n;return 0}
function VoiceAssistant({lang,onNavigate}){
  const [listening,setListening]=useState(false);
  const [open,setOpen]=useState(false);
  const [transcript,setTranscript]=useState('');
  const [message,setMessage]=useState('');
  const recognitionRef=React.useRef(null);
  const labels={
    en:{title:'Voice help',ready:'Ask for help or answer the current question.',listen:'Listening…',speak:'Speak',stop:'Stop',read:'Read aloud',example:'Try: “What is the next step?”',unsupported:'Voice recognition is not available in this browser. Try Google Chrome.'},
    hi:{title:'आवाज़ सहायता',ready:'मदद पूछें या वर्तमान प्रश्न का उत्तर दें।',listen:'सुन रहा है…',speak:'बोलें',stop:'रोकें',read:'जोर से पढ़ें',example:'उदाहरण: “अगला चरण क्या है?”',unsupported:'इस ब्राउज़र में आवाज़ पहचान उपलब्ध नहीं है। Google Chrome आज़माएँ।'},
    ta:{title:'குரல் உதவி',ready:'உதவி கேளுங்கள் அல்லது தற்போதைய கேள்விக்கு பதில் சொல்லுங்கள்.',listen:'கேட்கிறது…',speak:'பேசுங்கள்',stop:'நிறுத்து',read:'சத்தமாக வாசி',example:'உதாரணம்: “அடுத்த படி என்ன?”',unsupported:'இந்த உலாவியில் குரல் அடையாளம் கிடைக்கவில்லை. Google Chrome பயன்படுத்தவும்.'}
  }[lang]||null;
  const speak=React.useCallback((text)=>{if(!('speechSynthesis' in window)||!text)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=getSpeechLocale(lang);u.rate=.94;window.speechSynthesis.speak(u)},[lang]);
  const answerCommand=React.useCallback((clean)=>{
    const lower=clean.toLowerCase();
    const isNext=/\b(next|continue|proceed)\b|அடுத்த|தொடர|अगला|जारी/.test(lower);
    const isBack=/\b(back|previous)\b|பின்|முந்தைய|वापस|पिछला/.test(lower);
    const isBusiness=/business dashboard|business|வணிக டாஷ்போர்டு|வணிக|व्यवसाय डैशबोर्ड|व्यवसाय/.test(lower);
    const isEducation=/education dashboard|education|கல்வி டாஷ்போர்டு|கல்வி|शिक्षा डैशबோர்டு|शिक्षा/.test(lower);
    const isScheme=/scheme|திட்ட|योजना/.test(lower);
    const isDocument=/document|ஆவணம்|दस्तावेज/.test(lower);
    const isPartner=/partner|bank|வங்கி|கூட்டாளர்|बैंक|पार्टनर/.test(lower);
    const isApplication=/application|விண்ணப்ப|आवेदन/.test(lower);
    if(isNext){onNavigate?.('onboarding');window.dispatchEvent(new CustomEvent('aarambh:voice',{detail:{text:clean,lang,command:'next'}}));speak('Moving to the next question.');return;}
    if(isBack){window.dispatchEvent(new CustomEvent('aarambh:voice',{detail:{text:clean,lang,command:'back'}}));speak('Going back one question.');return;}
    if(isBusiness){onNavigate?.('business-dashboard');speak('Opening the business dashboard.');return;}
    if(isEducation){onNavigate?.('education-dashboard');speak('Opening the education dashboard.');return;}
    if(isScheme){onNavigate?.('schemes');speak('Opening scheme discovery.');return;}
    if(isDocument){onNavigate?.('documents');speak('Opening documents.');return;}
    if(isPartner){onNavigate?.('partners');speak('Opening partner matching.');return;}
    if(isApplication){onNavigate?.('applications');speak('Opening your applications.');return;}
    window.dispatchEvent(new CustomEvent('aarambh:voice',{detail:{text:clean,lang,command:'answer'}}));
  },[lang,onNavigate,speak]);
  const start=React.useCallback((openPanel=true)=>{
    const R=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!R){setMessage(labels.unsupported);if(openPanel)setOpen(true);return;}
    try{
      const r=new R();recognitionRef.current=r;r.lang=getSpeechLocale(lang);r.continuous=false;r.interimResults=true;r.maxAlternatives=1;
      r.onstart=()=>{setListening(true);if(openPanel)setOpen(true);setMessage(labels.listen)};
      r.onresult=e=>{let finalText='';let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const text=e.results[i][0]?.transcript||'';if(e.results[i].isFinal)finalText+=text;else interim+=text}const text=(finalText||interim).trim();if(text)setTranscript(text);if(finalText.trim()){const clean=finalText.trim();setMessage(clean);answerCommand(clean)}};
      r.onerror=e=>{setMessage(e.error==='not-allowed'?'Microphone permission was denied. Allow microphone access and try again.':'Voice recognition stopped. Try again.');setListening(false)};
      r.onend=()=>setListening(false);r.start();
    }catch{setListening(false);setMessage('Voice recognition could not start. Please try again.');if(openPanel)setOpen(true)}
  },[answerCommand,lang,labels]);
  const stop=()=>{try{recognitionRef.current?.stop()}catch{}setListening(false)};
  useEffect(()=>{const h=e=>start(!e.detail?.inline);window.addEventListener('aarambh:start-voice',h);return()=>window.removeEventListener('aarambh:start-voice',h)},[start]);
  return <div className={'voice-assistant '+(open?'voice-open ':'voice-collapsed ')+(listening?'voice-listening':'')}>
    {!open?<button className="voice-fab" onClick={()=>{setOpen(true);start()}} aria-label="Open voice help" title="Voice help"><Mic size={22}/></button>:<div className="voice-panel"><div className="voice-head"><div><Pill tone={listening?'success':''}><Mic size={14}/> {listening?labels.listen:labels.title}</Pill><p>{message||labels.ready}</p></div><button className="icon-btn" onClick={()=>{stop();setOpen(false)}} title="Minimize voice help"><X size={17}/></button></div><div className="voice-actions"><button className="voice-main" onClick={listening?stop:start}>{listening?<Square size={18}/>:<Mic size={20}/>}<span>{listening?labels.stop:labels.speak}</span></button>{transcript&&<button className="btn secondary" onClick={()=>speak(transcript)}><Volume2 size={17}/>{labels.read}</button>}</div><small>{labels.example}</small></div>}
  </div>
}

function Connectivity({userId}){
  const [online,setOnline]=useState(navigator.onLine);
  const [synced,setSynced]=useState('');
  useEffect(()=>{
    const on=()=>setOnline(true), off=()=>setOnline(false);
    window.addEventListener('online',on);window.addEventListener('offline',off);
    return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',off)};
  },[]);
  const sync=async()=>{
    try{if(userId)await syncPending(userId);setSynced(new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}))}catch{}
  };
  return <div className="connectivity" title={online?'Connected to the local AARAMBH service':'Offline mode'}><span className={online?'status-dot online':'status-dot'}>{online?<Wifi size={15}/>:<WifiOff size={15}/>}</span><span>{online?'Online':'Offline'}</span><small>{synced?'Synced '+synced:'Local data ready'}</small><button type="button" className="sync-btn" onClick={sync}><RefreshCw size={15}/> Sync</button></div>
}

function InlineVoiceButton({label='Answer by voice'}){return <button type="button" className="inline-voice-btn" onClick={()=>window.dispatchEvent(new CustomEvent('aarambh:start-voice',{detail:{inline:true}}))}><Mic size={18}/><span>{label}</span></button>}

